parameters.jsonBody:
={{ JSON.stringify({
  contents: [
    {
      parts: [
        {
          text: "You are an intelligent email triage assistant. Analyze the following email and extract structured data.

IMPORTANT RULES:
1. Extract ALL action items, to-dos, or tasks mentioned or implied
2. Extract ALL dates, deadlines, events, or appointments mentioned
3. Extract ALL flight information (airline, flight number, departure/arrival cities, times, dates, confirmation numbers)
4. Classify the email priority: high, medium, low
5. Determine if sender is likely an important contact (business partner, client, family, financial institution)

Respond ONLY with valid JSON in this exact format (no markdown, no backticks, no explanation):
{"classification": "todo | date | flight | informational | multiple", "priority": "high | medium | low", "is_important_contact": true, "todos": [{"task": "Description", "due_date": "YYYY-MM-DD or null", "priority": "high | medium | low"}], "dates": [{"event_name": "Name", "date": "YYYY-MM-DD", "time_start": "HH:MM or null", "time_end": "HH:MM or null", "location": "Location or null", "description": "Brief description"}], "flights": [{"airline": "Name", "flight_number": "Number or null", "confirmation_code": "Code or null", "departure_city": "City", "arrival_city": "City", "departure_date": "YYYY-MM-DD", "departure_time": "HH:MM or null", "arrival_date": "YYYY-MM-DD or null", "arrival_time": "HH:MM or null"}], "summary": "One-line summary"}

If a category has no items, return an empty array [].
For dates, use the current year if no year is specified.

---

FROM: " + $json.senderName + " <" + $json.sender + ">
SUBJECT: " + $json.subject + "
DATE: " + $json.date + "

BODY:
" + $json.body
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.1,
    maxOutputTokens: 8192,
    responseMimeType: "application/json"
  }
}) }}

parameters.jsCode:
// Parse Gemini response into structured JSON
const items = $input.all();
const emails = $('Extract Email Fields').all(); // Gets ALL original emails
const results = [];

for (let i = 0; i < items.length; i++) {
  try {
    const candidates = items[i].json.candidates;
    if (!candidates || !candidates[0] || !candidates[0].content || !candidates[0].content.parts) {
      throw new Error('Invalid Gemini response structure');
    }

    let aiResponse = candidates[0].content.parts[0].text;
    aiResponse = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    const parsed = JSON.parse(aiResponse);

    // Grabs the exact email data matching the current Gemini response index
    const emailData = emails[i].json; 

    results.push({
      json: {
        ...parsed,
        _email: {
          sender: emailData.sender,
          senderName: emailData.senderName,
          subject: emailData.subject,
          emailId: emailData.emailId,
          date: emailData.date
        }
      }
    });
  } catch (e) {
    const emailData = emails[i] ? emails[i].json : {};
    results.push({
      json: {
        classification: 'parse_error',
        error: e.message,
        rawResponse: JSON.stringify(items[i].json),
        _email: {
          sender: emailData.sender || '',
          subject: emailData.subject || '',
          emailId: emailData.emailId || ''
        }
      }
    });
  }
}

return results;

const input = $input.first().json;
const results = [];

// The || [] ensures it never crashes even if 'todos' is missing
for (const todo of (input.todos || [])) {
  results.push({
    json: {
      task: todo.task,
      due_date: todo.due_date,
      priority: todo.priority,
      email_subject: input._email.subject,
      email_sender: input._email.senderName || input._email.sender,
      email_date: input._email.date,
      is_important: input.is_important_contact
    }
  });
}

return results;

const input = $input.first().json;
const results = [];

for (const dateItem of (input.dates || [])) {
  let startDateTime = dateItem.date;
  let endDateTime = null;

  if (dateItem.time_start) {
    startDateTime = `${dateItem.date}T${dateItem.time_start}:00`;
  }
  if (dateItem.time_end) {
    endDateTime = `${dateItem.date}T${dateItem.time_end}:00`;
  } else if (dateItem.time_start) {
    const [hours, mins] = dateItem.time_start.split(':').map(Number);
    const endHour = String(hours + 1).padStart(2, '0');
    endDateTime = `${dateItem.date}T${endHour}:${String(mins).padStart(2, '0')}:00`;
  }

  results.push({
    json: {
      event_name: dateItem.event_name,
      date: dateItem.date,
      start: startDateTime,
      end: endDateTime,
      location: dateItem.location,
      description: `${dateItem.description}\n\nSource: Email from ${input._email.senderName || input._email.sender}\nSubject: ${input._email.subject}`,
      email_sender: input._email.senderName || input._email.sender,
      email_subject: input._email.subject
    }
  });
}

return results;

const input = $input.first().json;
const results = [];

for (const flight of (input.flights || [])) {
  let startDateTime = flight.departure_date;
  let endDateTime = flight.arrival_date || flight.departure_date;

  if (flight.departure_time) {
    startDateTime = `${flight.departure_date}T${flight.departure_time}:00`;
  }
  if (flight.arrival_time && flight.arrival_date) {
    endDateTime = `${flight.arrival_date}T${flight.arrival_time}:00`;
  } else if (flight.arrival_time) {
    endDateTime = `${flight.departure_date}T${flight.arrival_time}:00`;
  }

  const flightTitle = `✈️ ${flight.airline || 'Flight'} ${flight.flight_number || ''} - ${flight.departure_city} → ${flight.arrival_city}`.trim();

  let description = `Flight Details:\n`;
  description += `Airline: ${flight.airline || 'N/A'}\n`;
  description += `Flight: ${flight.flight_number || 'N/A'}\n`;
  description += `Confirmation: ${flight.confirmation_code || 'N/A'}\n`;
  description += `Route: ${flight.departure_city} → ${flight.arrival_city}\n`;
  description += `\nSource: Email from ${input._email.senderName || input._email.sender}\nSubject: ${input._email.subject}`;

  results.push({
    json: {
      flight_title: flightTitle,
      start: startDateTime,
      end: endDateTime,
      description: description,
      departure_city: flight.departure_city,
      arrival_city: flight.arrival_city,
      confirmation_code: flight.confirmation_code,
      email_sender: input._email.senderName || input._email.sender,
      email_subject: input._email.subject
    }
  });
}

return results;
